HEAD = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">\n<title>Odoo ERP System Overview &amp; Implementation Guide | Addis Tech PLC</title>\n<meta name="description" content="Odoo Enterprise Resource Planning (ERP) System Overview and Implementation Guide by Addis Tech PLC. Learn about ERP benefits, core applications, modules, industries, and our implementation methodology.">\n<meta name="theme-color" content="#1B1464">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap" rel="stylesheet">\n<script src="https://cdn.tailwindcss.com"></script>\n<script>\ntailwind.config = {\n  theme: {\n    extend: {\n      colors: {\n        brand:    \'#1B1464\',\n        \'brand-dark\': \'#0B0642\',\n        \'brand-deep\': \'#000C1D\',\n        accent:   \'#003B95\',\n        amber:    \'#FFA600\',\n        green:    \'#06A225\',\n        ice:      \'#E5F0FC\',\n        paper:    \'#FAFAFA\',\n        \'paper-2\':\'#F0F0FA\',\n        rule:     \'#E0E0EE\',\n        body:     \'#1A1A2E\',\n        muted:    \'#4A4A6A\',\n        \'table-h\':\'#1B1464\',\n      },\n      fontFamily: {\n        heading: [\'Outfit\',\'sans-serif\'],\n        body:    [\'Plus Jakarta Sans\',\'sans-serif\'],\n      }\n    }\n  }\n}\n</script>\n<style>\n/* ── Global Reset & Base ─────────────────────────────────────── */\n*{box-sizing:border-box;margin:0;padding:0;}\nhtml{scroll-behavior:smooth;background:#FAFAFA;}\nbody{font-family:\'Plus Jakarta Sans\',sans-serif;color:#1A1A2E;background:#FAFAFA;overflow-x:hidden;}\n\n/* ── Reading Progress Bar ────────────────────────────────────── */\n#progress-bar{position:fixed;top:0;left:0;height:3px;width:0%;\n  background:linear-gradient(90deg,#FFA600,#06A225);z-index:9999;\n  transition:width .1s linear;pointer-events:none;}\n\n/* ── Sticky Header ───────────────────────────────────────────── */\n#sticky-header{position:fixed;top:3px;left:0;right:0;z-index:1000;\n  background:#1B1464;border-bottom:1px solid rgba(255,255,255,.12);\n  transition:transform .3s ease,opacity .25s ease;transform:translateY(0);}\n#sticky-header.hidden-up{transform:translateY(-110%);opacity:0;pointer-events:none;}\n\n/* ── Section Chip Nav ────────────────────────────────────────── */\n#toc-nav{background:#15104E;border-bottom:1px solid rgba(255,255,255,.1);\n  overflow-x:auto;white-space:nowrap;scrollbar-width:none;-webkit-overflow-scrolling:touch;}\n#toc-nav::-webkit-scrollbar{display:none;}\n.toc-chip{display:inline-flex;align-items:center;padding:5px 12px;margin:6px 4px;\n  border-radius:9999px;font-size:.7rem;font-weight:600;font-family:\'Plus Jakarta Sans\',sans-serif;\n  color:rgba(240,240,255,.85);background:rgba(255,255,255,.08);\n  border:1px solid rgba(255,255,255,.12);text-decoration:none;\n  transition:all .2s;cursor:pointer;white-space:nowrap;flex-shrink:0;}\n.toc-chip.active,.toc-chip:hover{background:#FFA600;color:#000C1D;border-color:#FFA600;}\n\n/* ── Document Section Header ─────────────────────────────────── */\n.sec-pill{display:inline-flex;align-items:center;justify-content:center;\n  min-width:24px;height:24px;padding:0 7px;border-radius:9999px;\n  background:#1B1464;color:#fff;font-size:.65rem;font-weight:800;\n  font-family:\'Outfit\',sans-serif;letter-spacing:.03em;flex-shrink:0;}\n.sec-title{font-family:\'Outfit\',sans-serif;font-size:1.2rem;font-weight:700;color:#1B1464;line-height:1.3;}\n.sec-rule{border:none;border-top:1.5px solid #E0E0EE;margin:8px 0 18px 0;}\n\n/* ── Callout / Quote Box ─────────────────────────────────────── */\n.callout{background:#E5F0FC;border-left:3px solid #003B95;\n  padding:12px 14px;border-radius:0 8px 8px 0;margin:14px 0;\n  font-size:.84rem;line-height:1.55;color:#1A1A2E;font-style:italic;}\n\n/* ── Feature List Item ───────────────────────────────────────── */\n.feat-item{display:flex;gap:8px;align-items:flex-start;padding:8px 0;\n  border-bottom:1px solid #F0F0FA;}\n.feat-item:last-child{border-bottom:none;}\n.feat-dot{color:#FFA600;font-size:.9rem;flex-shrink:0;margin-top:.12rem;line-height:1.5;}\n.feat-title{font-weight:700;color:#1B1464;font-size:.84rem;font-family:\'Plus Jakarta Sans\',sans-serif;}\n.feat-desc{font-size:.82rem;color:#3A3A5A;line-height:1.5;}\n\n/* ── Responsive Table ────────────────────────────────────────── */\n.tbl-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:14px 0;border-radius:8px;\n  border:1px solid #D0D0E0;}\ntable{width:100%;border-collapse:collapse;font-size:.8rem;min-width:400px;}\nthead tr{background:#1B1464;color:#fff;}\nth{padding:9px 12px;text-align:left;font-weight:700;font-size:.75rem;\n  font-family:\'Plus Jakarta Sans\',sans-serif;letter-spacing:.03em;text-transform:uppercase;}\ntd{padding:8px 12px;border-bottom:1px solid #E0E0EE;vertical-align:top;\n  font-size:.8rem;color:#1A1A2E;line-height:1.45;}\ntr:nth-child(even) td{background:#F5F5FF;}\ntr:last-child td{border-bottom:none;}\n\n/* ── Accordion (Section 6) ───────────────────────────────────── */\n.acc-item{border-left:3px solid #D0D0E0;background:#F5F5FF;\n  margin-bottom:8px;border-radius:0 8px 8px 0;overflow:hidden;\n  transition:border-color .2s;}\n.acc-item.open{border-left-color:#1B1464;background:#fff;}\n.acc-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;\n  gap:10px;padding:12px 14px;background:none;border:none;cursor:pointer;text-align:left;}\n.acc-num{display:inline-flex;align-items:center;justify-content:center;\n  min-width:26px;height:26px;border-radius:6px;background:#1B1464;\n  color:#FFA600;font-size:.7rem;font-weight:800;font-family:\'Outfit\',sans-serif;flex-shrink:0;}\n.acc-name{font-family:\'Outfit\',sans-serif;font-size:.88rem;font-weight:700;\n  color:#1B1464;line-height:1.3;flex:1;}\n.acc-chevron{flex-shrink:0;width:18px;height:18px;color:#888;transition:transform .25s;}\n.acc-item.open .acc-chevron{transform:rotate(180deg);color:#1B1464;}\n.acc-body{display:none;padding:0 14px 14px 14px;}\n.acc-item.open .acc-body{display:block;}\n.acc-subtitle{font-style:italic;font-size:.82rem;color:#003B95;font-weight:600;\n  margin-bottom:8px;line-height:1.4;}\n.acc-intro{font-size:.82rem;color:#3A3A5A;line-height:1.55;margin-bottom:10px;}\n.acc-features-label{font-size:.72rem;font-weight:700;color:#888;\n  letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px;margin-top:8px;}\n\n/* ── Industry Tabs (Section 8) ───────────────────────────────── */\n.ind-tabs{display:flex;gap:6px;overflow-x:auto;white-space:nowrap;\n  padding:4px 0 8px 0;scrollbar-width:none;-webkit-overflow-scrolling:touch;}\n.ind-tabs::-webkit-scrollbar{display:none;}\n.ind-tab{padding:5px 12px;border-radius:9999px;font-size:.72rem;font-weight:600;\n  font-family:\'Plus Jakarta Sans\',sans-serif;background:#F0F0FA;\n  border:1px solid #D0D0E0;color:#4A4A6A;cursor:pointer;\n  transition:all .2s;flex-shrink:0;white-space:nowrap;}\n.ind-tab.active{background:#1B1464;color:#fff;border-color:#1B1464;}\n.ind-panel{display:none;}\n.ind-panel.active{display:block;}\n.ind-panel-title{font-family:\'Outfit\',sans-serif;font-size:.95rem;\n  font-weight:700;color:#1B1464;margin-bottom:4px;}\n.ind-panel-intro{font-size:.8rem;color:#4A4A6A;line-height:1.5;margin-bottom:10px;}\n\n/* ── Phase Steps ─────────────────────────────────────────────── */\n.phase-step{display:flex;gap:14px;padding:14px;background:#F5F5FF;\n  border-radius:8px;margin-bottom:10px;border-left:3px solid #1B1464;}\n.phase-num{flex-shrink:0;width:34px;height:34px;border-radius:50%;\n  background:#1B1464;color:#FFA600;font-family:\'Outfit\',sans-serif;\n  font-size:.85rem;font-weight:800;display:flex;align-items:center;justify-content:center;}\n.phase-title{font-family:\'Outfit\',sans-serif;font-size:.9rem;font-weight:700;\n  color:#1B1464;margin-bottom:2px;}\n.phase-subtitle{font-size:.78rem;color:#003B95;font-style:italic;margin-bottom:6px;font-weight:500;}\n.phase-body{font-size:.8rem;color:#3A3A5A;line-height:1.5;}\n.phase-arrow{text-align:center;font-size:1.1rem;color:#1B1464;\n  margin:4px 0;font-weight:700;opacity:.5;}\n\n/* ── Team Card ───────────────────────────────────────────────── */\n.team-card{background:#fff;border:1px solid #E0E0EE;border-radius:10px;\n  padding:14px;display:flex;gap:12px;align-items:flex-start;}\n.team-avatar{flex-shrink:0;width:42px;height:42px;border-radius:10px;\n  background:#1B1464;color:#FFA600;font-family:\'Outfit\',sans-serif;\n  font-size:.95rem;font-weight:800;display:flex;align-items:center;justify-content:center;}\n.team-name{font-family:\'Outfit\',sans-serif;font-size:.9rem;font-weight:700;color:#1B1464;}\n.team-role{font-size:.75rem;font-weight:600;color:#003B95;margin-bottom:4px;}\n.team-exp{display:inline-block;font-size:.68rem;font-weight:700;\n  color:#047A1B;background:#E8F8ED;padding:1px 8px;border-radius:999px;margin-bottom:5px;}\n.team-expertise-label{font-size:.68rem;font-weight:700;color:#888;\n  text-transform:uppercase;letter-spacing:.05em;margin-bottom:1px;}\n.team-expertise{font-size:.77rem;color:#3A3A5A;line-height:1.4;margin-bottom:5px;}\n.team-impact-label{font-size:.68rem;font-weight:700;color:#888;\n  text-transform:uppercase;letter-spacing:.05em;margin-bottom:1px;}\n.team-impact{font-size:.77rem;color:#3A3A5A;line-height:1.45;}\n\n/* ── Next Steps ──────────────────────────────────────────────── */\n.next-step{border:1px solid #E0E0EE;border-radius:10px;padding:14px;\n  margin-bottom:10px;background:#fff;}\n.next-step-header{display:flex;gap:10px;align-items:flex-start;margin-bottom:8px;}\n.next-step-num{flex-shrink:0;width:32px;height:32px;border-radius:50%;\n  background:#FFA600;color:#000C1D;font-family:\'Outfit\',sans-serif;\n  font-size:.85rem;font-weight:800;display:flex;align-items:center;justify-content:center;}\n.next-step-title{font-family:\'Outfit\',sans-serif;font-size:.88rem;font-weight:700;color:#1B1464;}\n.action-label,.outcome-label{font-size:.68rem;font-weight:700;\n  text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px;}\n.action-label{color:#003B95;}\n.outcome-label{color:#047A1B;}\n.action-text,.outcome-text{font-size:.8rem;color:#3A3A5A;line-height:1.5;margin-bottom:6px;}\n\n/* ── Contact Section ─────────────────────────────────────────── */\n.contact-item{display:flex;align-items:center;gap:10px;padding:10px 12px;\n  background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);\n  border-radius:8px;text-decoration:none;color:#fff;font-size:.82rem;margin-bottom:8px;}\n.contact-icon{flex-shrink:0;width:30px;height:30px;border-radius:7px;\n  background:rgba(255,166,0,.2);color:#FFA600;\n  display:flex;align-items:center;justify-content:center;}\n\n/* ── Bottom Dock ─────────────────────────────────────────────── */\n#bottom-dock{position:fixed;bottom:0;left:0;right:0;z-index:1000;\n  background:rgba(27,20,100,.96);backdrop-filter:blur(12px);\n  -webkit-backdrop-filter:blur(12px);border-top:1px solid rgba(255,255,255,.12);\n  padding:7px 12px;padding-bottom:max(7px,env(safe-area-inset-bottom));\n  transition:transform .3s ease;}\n#bottom-dock.hidden-down{transform:translateY(110%);}\n.dock-inner{max-width:680px;margin:0 auto;display:grid;\n  grid-template-columns:1fr 1fr 1.4fr auto;gap:6px;align-items:center;}\n.dock-btn{display:flex;flex-direction:column;align-items:center;gap:2px;\n  background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);\n  color:#fff;border-radius:7px;padding:5px 4px;text-decoration:none;\n  font-size:.65rem;font-weight:600;min-height:40px;justify-content:center;}\n.dock-cta{background:#FFA600;color:#000C1D;border:none;font-weight:800;\n  font-size:.75rem;flex-direction:row;gap:5px;min-height:40px;}\n.dock-top{width:40px;min-height:40px;border-radius:50%;padding:0;\n  flex-direction:row;justify-content:center;}\n\n/* ── Back to Top ─────────────────────────────────────────────── */\n#back-top{position:fixed;bottom:70px;right:14px;z-index:900;\n  display:none;width:38px;height:38px;border-radius:50%;\n  background:#1B1464;color:#fff;border:none;cursor:pointer;\n  align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(27,20,100,.35);}\n#back-top.show{display:flex;}\n\n/* ── Body Padding for fixed header+dock ──────────────────────── */\nbody{padding-top:102px;padding-bottom:66px;}\n\n/* ── Print ───────────────────────────────────────────────────── */\n@media print{\n  #sticky-header,#bottom-dock,#back-top,#toc-nav,#progress-bar{display:none!important;}\n  body{padding:0!important;}\n  .acc-body{display:block!important;}\n  .ind-panel{display:block!important;margin-bottom:12px;}\n}\n</style>\n</head>'